// Generic merge - this node never needs editing even when students
// replace the sample code above with their own real framework files.
const chatInput = $('When chat message received').item.json.chatInput;
const { pageObjectSample, testSpecSample, conventions } = $json;

const contextPack = `SAMPLE PAGE OBJECT (pages/LoginPage.ts) - replicate this exact style:
${pageObjectSample}

SAMPLE TEST SPEC (tests/login.spec.ts) - replicate this exact style:
${testSpecSample}

${conventions}

NOTE TO STUDENT: The two code samples and conventions above are a generic placeholder.
In a real project, replace them in the "Context Pack - Framework Inputs" node with an
actual Page Object and test spec copied from your own automation framework. Nothing
else in this workflow needs to change.`;

return [{
  json: {
    chatInput,
    contextPack
  }
}];

const result = $json.output;

let md = `### Generated Playwright Files\n\n`;
md += `**Page Object File:** \`${result.pageObjectFileName}\`\n\n`;
md += "```typescript\n" + result.pageObjectCode + "\n```\n\n";
md += `**Test Spec File:** \`${result.testSpecFileName}\`\n\n`;
md += "```typescript\n" + result.testCode + "\n```\n\n";

if (result.missingLocators && result.missingLocators.length > 0) {
  md += `**MISSING LOCATORS - the AI did NOT guess these. Please supply them and re-run:**\n`;
  for (const m of result.missingLocators) {
    md += `- ${m}\n`;
  }
  md += `\n`;
} else {
  md += `All required locators were supplied - no selectors were guessed.\n\n`;
}

md += `**Notes:** ${result.notes}\n\n`;
md += `Two downloadable .ts files are attached to this message - save them directly into your framework's /pages and /tests folders.`;

// Build real downloadable .ts files from the generated code strings.
// n8n lets a Code node attach binary data directly on the returned item,
// as long as "data" is a base64 string - no extra node type is needed.
return [{
  json: { output: md },
  binary: {
    pageObjectFile: {
      data: Buffer.from(result.pageObjectCode, 'utf-8').toString('base64'),
      mimeType: 'text/plain',
      fileName: result.pageObjectFileName.split('/').pop(),
      fileExtension: 'ts'
    },
    testSpecFile: {
      data: Buffer.from(result.testCode, 'utf-8').toString('base64'),
      mimeType: 'text/plain',
      fileName: result.testSpecFileName.split('/').pop(),
      fileExtension: 'ts'
    }
  }
}];
